 window.addEventListener('keydown',e=>{if(!ready||!active||!visible||document.querySelector('dialog[open]')||/INPUT|SELECT|TEXTAREA/.test(document.activeElement?.tagName))return;if(['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code)&&viewer.contains(document.activeElement)){e.preventDefault();keys.add(e.code);}if(e.key==='Escape'){stopMovement();closeSelection();stopGuide();}});window.addEventListener('keyup',e=>keys.delete(e.code));
