 async validateModels(){initRenderer();const results=[];for(const p of products){const response=await fetch(p.model),data=await response.arrayBuffer(),gltf=await loader.parseAsync(data,new URL('.',new URL(p.model,location.href)).href);let meshes=0;gltf.scene.traverse(o=>{if(o.isMesh)meshes++;});results.push({sku:p.sku,meshes,root:!!rootIn(gltf.scene),parts:moving(rootIn(gltf.scene)).length});dispose(gltf.scene);}return results;}
